function clamp01(v) {
  if (v < 0) return 0;
  if (v > 1) return 1;
  return v;
}

export function getGrassColor(temp, humidity) {
  const t = clamp01(temp);
  const h = clamp01(humidity) * t;
  const x = Math.max(0, Math.min(255, Math.trunc((1 - t) * 255)));
  const y = Math.max(0, Math.min(255, Math.trunc((1 - h) * 255)));
  return grassBuffer[(y << 8) | x] >>> 0;
}

export function getFoliageColor(temp, humidity) {
  const t = clamp01(temp);
  const h = clamp01(humidity) * t;
  const x = Math.max(0, Math.min(255, Math.trunc((1 - t) * 255)));
  const y = Math.max(0, Math.min(255, Math.trunc((1 - h) * 255)));
  return foliageBuffer[(y << 8) | x] >>> 0;
}

export function unpackRgb(rgb) {
  const srgbToLinear = (v) => {
    if (v <= 0.04045) return v / 12.92;
    return Math.pow((v + 0.055) / 1.055, 2.4);
  };
  return {
    r: srgbToLinear(((rgb >>> 16) & 255) / 255),
    g: srgbToLinear(((rgb >>> 8) & 255) / 255),
    b: srgbToLinear((rgb & 255) / 255)
  };
}
